import java.util.*;

class Solution {
    public void moveZeroes(int[] nums) {
        int w = 0; // next position for a non-zero value
        for (int x : nums) {
            if (x != 0) nums[w++] = x;
        }
        while (w < nums.length) nums[w++] = 0; // fill the tail with zeros
    }
}

